// 小米 MiMo TTS 语音合成插件 (简化接口)
let apiKey = ttsrv.userVars['apiKey'] || ''
let baseUrl = ttsrv.userVars['baseUrl'] || 'https://api.xiaomimimo.com'

let voices = [
    {Locale: 'zh-CN', ShortName: '冰糖', LocalName: '冰糖', Gender: 'Female'},
    {Locale: 'zh-CN', ShortName: '茉莉', LocalName: '茉莉', Gender: 'Female'},
    {Locale: 'zh-CN', ShortName: '苏打', LocalName: '苏打', Gender: 'Male'},
    {Locale: 'zh-CN', ShortName: '白桦', LocalName: '白桦', Gender: 'Male'},
    {Locale: 'en-US', ShortName: 'Mia', LocalName: 'Mia', Gender: 'Female'},
    {Locale: 'en-US', ShortName: 'Chloe', LocalName: 'Chloe', Gender: 'Female'},
    {Locale: 'en-US', ShortName: 'Milo', LocalName: 'Milo', Gender: 'Male'},
    {Locale: 'en-US', ShortName: 'Dean', LocalName: 'Dean', Gender: 'Male'},
]

let currentVoices = new Map()

// 简化的 TTS 调用函数
tunction synthesizeTTS(text, voice, style) {
    let userContent = '请朗读以下文本'
    if (style) {
        userContent += '，用' + style + '的语气'
    }

    return {
        model: ttsrv.tts.data['model'] || 'mimo-v2.5-tts',
        messages: [
            {role: 'user', content: userContent},
            {role: 'assistant', content: text}
        ],
        audio: {voice: voice, format: 'wav'},
        stream: false
    }
}

let PluginJS = {
    "name": "小米 MiMo TTS (简化版)",
    "id": "com.xiaomi.mimo.tts.simple",
    "author": "TTS Server",
    "version": 11,

    "getAudio": function (text, locale, voice, rate, volume, pitch) {
        if (!apiKey || apiKey.trim() === '') {
            throw "请先在变量设置中配置 API Key"
        }

        let style = ttsrv.tts.data['style'] || ''
        let requestBody = synthesizeTTS(text, voice || '冰糖', style)

        let headers = {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + apiKey
        }

        let resp = ttsrv.httpPost(
            baseUrl + '/v1/chat/completions',
            JSON.stringify(requestBody),
            headers
        )

        if (resp.code() !== 200) {
            if (resp.code() === 401) {
                throw "401: API Key 无效"
            }
            throw "HTTP错误: " + resp.code()
        }

        let respText = resp.body().string()
        let respJson = JSON.parse(respText)

        if (respJson.choices && respJson.choices.length > 0) {
            let message = respJson.choices[0].message
            if (message.audio && message.audio.data) {
                let audioBytes = java.util.Base64.getDecoder().decode(message.audio.data)
                return new java.io.ByteArrayInputStream(audioBytes)
            }
        }

        throw "响应中未找到音频数据"
    },
}

let EditorJS = {
    "getAudioSampleRate": function (locale, voice) {
        return 24000
    },

    "getLocales": function () {
        let locales = new Array()
        voices.forEach(function (v) {
            let loc = v.Locale
            if (!locales.includes(loc)) {
                locales.push(loc)
            }
        })
        return locales
    },

    "getVoices": function (locale) {
        currentVoices = new Map()
        voices.forEach(function (v) {
            if (v.Locale === locale) {
                currentVoices.set(v.ShortName, v)
            }
        })

        let mm = {}
        for (let [key, value] of currentVoices.entries()) {
            mm[key] = new java.lang.String(value.LocalName + ' (' + key + ')')
        }
        return mm
    },

    "onLoadData": function () {
    },

    "onLoadUI": function (ctx, linerLayout) {
        let modelSpinner = JSpinner(ctx, "模型 (Model)")
        modelSpinner.items = [
            Item("MiMo TTS v2.5 (预置音色)", "mimo-v2.5-tts"),
            Item("MiMo TTS VoiceDesign (音色设计)", "mimo-v2.5-tts-voicedesign"),
            Item("MiMo TTS VoiceClone (音色克隆)", "mimo-v2.5-tts-voiceclone"),
        ]
        linerLayout.addView(modelSpinner)
        ttsrv.setMargins(modelSpinner, 2, 4, 0, 0)

        let currentModel = ttsrv.tts.data['model'] || 'mimo-v2.5-tts'
        let modelPos = 0
        if (currentModel === 'mimo-v2.5-tts-voicedesign') modelPos = 1
        if (currentModel === 'mimo-v2.5-tts-voiceclone') modelPos = 2
        modelSpinner.selectedPosition = modelPos

        modelSpinner.setOnItemSelected(function (spinner, pos, item) {
            ttsrv.tts.data['model'] = item.value
        })

        let styleSpinner = JSpinner(ctx, "风格 (Style)")
        styleSpinner.items = [
            Item("默认", ""),
            Item("温柔", "温柔"),
            Item("专业", "专业"),
            Item("活泼", "活泼"),
            Item("严肃", "严肃"),
        ]
        linerLayout.addView(styleSpinner)
        ttsrv.setMargins(styleSpinner, 2, 4, 0, 0)

        let currentStyle = ttsrv.tts.data['style'] || ''
        let stylePos = 0
        if (currentStyle === '温柔') stylePos = 1
        if (currentStyle === '专业') stylePos = 2
        if (currentStyle === '活泼') stylePos = 3
        if (currentStyle === '严肃') stylePos = 4
        styleSpinner.selectedPosition = stylePos

        styleSpinner.setOnItemSelected(function (spinner, pos, item) {
            ttsrv.tts.data['style'] = item.value
        })
    },

    "onVoiceChanged": function (locale, voice) {
    }
}
